"""All symmetries of four quadrilateral families, Atanasyan 7–9, exercise 1271."""
import argparse
import json
from rotated_circles_lines import diagram
from rotation_constructions import turning_arrow
from translations_and_rotations import lesson
from vector_scaling import BOOK,ROOT

OUT=ROOT/'geometry-course/textbook/data/quadrilateral-symmetries.json'
EDGES=[('A','B'),('B','C'),('C','D'),('D','A')]


def picture(kind,a,b,title):
    center=(0,0);axes=[];arcs=[]
    if kind=='slant':
        pts={'A':(-a-1,-b),'B':(a-1,-b),'C':(a+1,b),'D':(-a+1,b),'T':center}
    elif kind=='rhombus':
        pts={'A':(a,0),'B':(0,b),'C':(-a,0),'D':(0,-b),'T':center}
        axes=[((-a-1,0),(a+1,0)),((0,-b-1),(0,b+1))]
    elif kind=='trap':
        pts={'A':(-a,0),'B':(a,0),'C':(b,3),'D':(-b,3)}
        axes=[((0,-.7),(0,3.7))]
    else:
        pts={'A':(-a,-b),'B':(a,-b),'C':(a,b),'D':(-a,b),'T':center}
        axes=[((-a-1,0),(a+1,0)),((0,-b-1),(0,b+1))]
        if a==b:axes.extend([((-a-.55,-a-.55),(a+.55,a+.55)),((-a-.55,a+.55),(a+.55,-a-.55))])
    if kind!='trap':arcs=turning_arrow(center,pts['A'],90 if kind=='square' else 180)
    return diagram(title,pts,EDGES,[*axes,*arcs])


def oblique():
    return lesson(1271,'а',327,'Найди внутренние симметрии параллелограмма. Какие из них есть всегда и какие появляются в частных случаях?',
      'Пересечение диагоналей T является центром симметрии: полуоборот меняет A с C и B с D. Возьмём непрямоугольный параллелограмм с разными смежными сторонами. Его острая вершина может перейти лишь в одну из двух острых. После её выбора длины соседних сторон однозначно задают образы двух соседей. Получились только тождественное движение и полуоборот; внутренней симметрией считаем лишь полуоборот. У прямоугольника с разными сторонами и у неквадратного ромба появляются две оси. У квадрата четыре оси и три нетождественных поворота.',
      [('Проследи пары противоположных вершин','В первом рисунке T — общая середина AC и BD. Поворот на 180° совмещает весь параллелограмм с собой.','Не всякая диагональ параллелограмма служит осью зеркального отражения.'),
       ('Исключи лишние движения','Во второй схеме углы острые и тупые, а соседние стороны различной длины. После выбора образа острой вершины длинная сторона должна перейти в длинную, короткая — в короткую.','Отражение, меняющее местами длинную и короткую стороны, не сохраняло бы расстояния.'),
       ('Разбери квадрат отдельно','В третьей схеме смежные стороны стали равными и угол прямой. Посчитай четыре оси и три поворота.','Не прибавляй центральную симметрию ещё раз: это уже поворот на 180°. Если угол прямой, но длины сторон разные, осей только две.')],
      [picture('slant',3,1,'Полуоборот обычного параллелограмма'),picture('slant',4,2,'Неравные стороны и два острых угла'),picture('square',2,2,'Частный случай квадрата')],
      [('Сколько нетождественных движений сохраняют второй параллелограмм?','1','В нём остаётся только полуоборот.'),('Сколько внутренних симметрий у квадрата на третьей схеме?','7','Четыре отражения и три поворота.')],
      'Движение сохраняет и длину стороны, и угол при вершине. По образам трёх неколлинеарных вершин движение определяется однозначно.',
      'Начни с полуоборота, а остальные возможности проверь по длинам и углам.',
      'T — пересечение диагоналей. На первых двух схемах показан полуоборот, на последней также отмечены все оси квадрата.',
      'Назови обязательную симметрию и объясни, как ответ меняется у прямоугольника, ромба и квадрата.',refs=[124,127])


def rectangle():
    return lesson(1271,'б',327,'Перечисли внутренние симметрии прямоугольника и назови отличия в случае квадрата.',
      'У прямоугольника с разными смежными сторонами осей две: это прямые через середины противоположных сторон. Ещё есть полуоборот вокруг центра. Других движений нет. Образ одной вершины выбирается четырьмя способами; у её соседей разные расстояния от неё, поэтому выбор образа этой вершины определяет образы соседей. Итак, всего четыре движения с учётом тождественного и три внутренние симметрии. У квадрата к двум осям прибавляются обе диагонали, а к полуобороту — два поворота на 90° в разных направлениях.',
      [('Найди средние прямые','У первой фигуры длинные стороны остаются длинными при любом движении. Проведи оси через середины пар противоположных сторон.','Диагональное отражение поменяло бы роли длинной и короткой сторон и не совместило бы фигуры.'),
       ('Проверь оба отражения','На второй схеме три движения видны отдельно: два отражения и полуоборот. Посчитай только оси отражения.','Точка T — центр. Ось — это целая прямая, поэтому центр не считается третьей осью.'),
       ('Уравняй стороны','В квадрате исчезает ограничение на две разные длины. Обе диагонали становятся осями. Добавь их к двум средним прямым.','Ответ про оси отличается от общего числа внутренних симметрий квадрата.')],
      [picture('rect',3,1,'Прямоугольник со сторонами 6 и 2'),picture('rect',4,2,'Две средние прямые и полуоборот'),picture('square',2,2,'Диагональные оси квадрата')],
      [('Сколько осей отражения имеет второй прямоугольник?','2','Одна ось параллельна длинным сторонам, другая — коротким.'),('Сколько осей отражения у третьей фигуры?','4','У квадрата есть также две диагональные оси.')],
      'У несмежных сторон прямоугольника равны длины. Неравенство длин смежных сторон исключает поворот на 90° и диагональное отражение.',
      'Проверь образ двух соседних сторон, имеющих разные длины.',
      'Прямые обозначают оси. Изогнутая стрелка обозначает один из допустимых поворотов.',
      'Перечисли оси и повороты для прямоугольника с разными сторонами, а затем для квадрата.',refs=[124,127])


def rhombus():
    return lesson(1271,'в',327,'Найди все внутренние симметрии ромба. Отдельно рассмотри ромб с прямым углом.',
      'Обе диагонали ромба являются осями: каждая перпендикулярна другой в её середине, а концы своей диагонали при отражении неподвижны. Ещё существует симметрия относительно точки их пересечения T. Если ромб не квадрат, у него две острые вершины и две тупые. У образа выбранной острой вершины два варианта, у образа соседней тупой — ещё два. Остальные вершины тогда определены как противоположные. Это даёт не более четырёх движений, и все они уже найдены вместе с тождественным. В случае квадрата имеем четыре оси и три нетождественных поворота.',
      [('Отрази относительно диагонали','На первом рисунке AC и BD перпендикулярны и делятся пополам. Ось AC меняет B и D, оставляя A и C на месте. Вторая диагональ действует аналогично.','Равенства всех сторон мало, чтобы любая прямая через центр стала осью.'),
       ('Посчитай оси вытянутого ромба','На второй схеме AC длиннее BD. Острая вершина не может перейти в тупую. Выбери образы двух соседних вершин и проверь уже найденные движения.','Поворот на 90° обменял бы длинную и короткую диагонали. Движение не может изменить её длину.'),
       ('Перейди к прямому углу','Ромб с прямым углом — квадрат. Прибавь две средние прямые как оси и два поворота на четверть оборота к уже известным симметриям.','Снова различай число осей и число всех внутренних симметрий.')],
      [picture('rhombus',3,2,'Диагонали служат осями'),picture('rhombus',4,2,'Неравные диагонали'),picture('square',2,2,'Ромб с прямым углом')],
      [('Сколько осей у второго ромба?','2','Это обе его диагонали.'),('Сколько нетождественных симметрий у третьего ромба?','7','Третий ромб — квадрат: четыре оси и три поворота.')],
      'Ромб является параллелограммом с равными сторонами. Его диагонали взаимно перпендикулярны и делят друг друга пополам.',
      'Проверь каждую диагональ отражением, затем проверь точку их пересечения полуоборотом.',
      'Оси на первых двух схемах проходят через вершины ромба. В квадрате к ним добавляются две другие прямые.',
      'Объясни, почему обе диагонали являются осями. Посчитай также повороты и особый случай квадрата.',refs=[124,127])


def isosceles_trapezoid():
    return lesson(1271,'г',327,'Найди внутренние симметрии равнобедренной трапеции, у которой основания разной длины.',
      'Срединные перпендикуляры к основаниям совпадают. Отражение в этой прямой меняет концы каждого основания местами и совмещает равные боковые стороны. Это единственная внутренняя симметрия. Любое движение сохраняет пару параллельных сторон. Основания различаются по длине, поэтому каждое должно перейти в себя. Их середины — две различные неподвижные точки. Единственные движения, фиксирующие обе, — тождественное и отражение в проходящей через них прямой. В частности, полуоборот не может обменять неравные основания.',
      [('Соедини середины оснований','На первом рисунке от середины короткого основания опущен перпендикуляр к длинному. Он проходит через середины обоих.','Не называй горизонтальную среднюю линию осью. Она поменяла бы местами основания разной длины.'),
       ('Сравни два выступа','Во второй схеме длинное основание 8, короткое 4. По обеим сторонам от короткого остаются равные выступы. Найди длину одного.','Разность оснований относится сразу к двум выступам.'),
       ('Оставь только одно отражение','В третьей схеме длины изменились, но основания по-прежнему различны, их середины неподвижны. Перечисли нетождественные движения.','У трапеции с разными основаниями отсутствует центральная симметрия.')],
      [picture('trap',3,1,'Ось через середины'),picture('trap',4,2,'Сравни основания 8 и 4'),picture('trap',5,3,'Проверь другой размер трапеции')],
      [('Какой длины каждый выступ при основаниях 8 и 4?','2','Раздели разность оснований 4 пополам.'),('Сколько внутренних симметрий у третьей трапеции?','1','Остаётся отражение в прямой через середины оснований.')],
      'У движения, фиксирующего две различные точки, остаются два варианта: сохранить всю плоскость на месте или отразить её в прямой через эти точки.',
      'Проверь, могут ли основания поменяться местами. Найди две точки, которые обязательно останутся на месте.',
      'На всех трёх схемах показана единственная ось. A и B лежат на большем основании.',
      'Обоснуй симметрию относительно указанной прямой и объясни, почему других внутренних симметрий нет.',refs=[123,124,127])


if __name__=='__main__':
    parser=argparse.ArgumentParser()
    parser.add_argument('--check',action='store_true')
    rows=[oblique(),rectangle(),rhombus(),isosceles_trapezoid()]
    raw=json.dumps({'bookId':BOOK,'lessons':rows},ensure_ascii=False,separators=(',',':'))+'\n'
    if parser.parse_args().check:
        assert OUT.read_text()==raw
    else:
        OUT.write_text(raw)
